// GENERATED-equivalent of desktop/qml/ActivityTypes.qml (itself generated by
// tools/gen_activity_qml.py from assets/activity_types.json). The Android app previously had
// no per-sport colour at all (LogListScreen tints every activity glyph with the theme muted
// colour), so the Calendar/Totals ports - which are all ABOUT per-sport colour - need the
// same 84-entry id->{name,colour} table and the same name-resolution the desktop pages rely
// on (ActivityTypes.forName()). Only the colour+name+id are ported here, not the SVG glyphs:
// Android draws activity icons from Icon.tsx's own monochrome set (see LogListScreen's
// activityIconName), and nothing on Android renders the per-sport SVG the way desktop's
// ActivityBadge does. Keep this in sync with assets/activity_types.json if that file changes.

import { IconName } from '../components/ui/Icon';

