// desktop ActivityTypes.qml's own _nameAliases - an Ambit "Walk" sport mode and a
// Kailash/Garmin "Walk" activity must resolve to the same id so they share a colour and a
// Totals bucket (see TotalsPage.qml's header comment). Keys/values are already normalised
// (lowercased, punctuation-stripped) the same way forName() normalises its input.
const NAME_ALIASES: Record<string, string> = {
  walk: 'walking',
};

const UNSPECIFIED = ACTIVITY_TYPES[1];

function normalise(s: string): string {
  return s.toLowerCase().replace(/[^a-z0-9]/g, '');
}

// Exact port of desktop ActivityTypes.forName(): case-insensitive, punctuation-insensitive,
// alias-aware, device-independent. Anything unrecognised falls back to "Unspecified sport"
// (id 1) rather than guessing - identical behaviour to the QML, so a mode a user renamed on
// the watch still lands in the right colour/bucket wherever both apps recognise the name.
export function activityForName(name: string | null | undefined): ActivityType {
  if (!name) return UNSPECIFIED;
  let want = normalise(String(name));
  if (NAME_ALIASES[want] !== undefined) want = NAME_ALIASES[want];
  for (const key of Object.keys(ACTIVITY_TYPES)) {
    const e = ACTIVITY_TYPES[Number(key)];
    if (normalise(e.name) === want) return e;
  }
  return UNSPECIFIED;
}

export function colorForName(name: string | null | undefined): string {
  return activityForName(name).color;
}

// ─── Activity icon glyphs (Android's monochrome Icon.tsx set) ──────────────────
// Ported from LogListScreen so both the activity log and the sport-mode list draw the same
// per-sport icon, keyed on the lowercased activity name (ACTIVITY_TYPES[id].name or a log's
// activity_type). Falls back to the generic 'activity' glyph for a name with no dedicated
// codepoint in this app's subset (e.g. swimming/transition) - the colour still tells sports
// apart. André, 2026-08-17.
export const ACTIVITY_ICON_NAMES: Record<string, IconName> = {
  'course à pied':        'running',
  'running':               'running',
  'trail running':         'running',
  'cyclisme':              'cycling',
  'cycling':               'cycling',
  'vtt':                   'cycling',
  'mountain biking':       'cycling',
  'randonnée':             'walking',
  'marche':                'walking',
  'trekking':              'walking',
  'hiking':                'walking',
  'trail':                 'mountain',
  'alpinisme':             'mountain',
  'ski alpin':             'mountain',
  'ski de fond':           'mountain',
  'ski de randonnée':      'mountain',
  'skiing':                'mountain',
  'cross country skiing':  'mountain',
  'snowboard':             'mountain',
};

export function activityIconName(type: string | null | undefined): IconName {
  return ACTIVITY_ICON_NAMES[(type ?? '').toLowerCase()] ?? 'activity';
}
